// Original public-output adapter. Descriptive measurements, never a chip pass band.
package main

import("encoding/csv";"encoding/json";"flag";"fmt";"os";"strconv")
const history_version="common-held-public-adapter-v1"
const history_method_sha="153051a625c56714542a0688040289b31dd3cf77a318c4225c5c64af447db582"
type history_job struct{input,marker,column,marker_column,timing_path,method_path,profile,out,curve,noop,calibration string; right,left []float64; timing history_timing; binding map[string]interface{}}
func main(){job:=history_job{};flag.StringVar(&job.column,"column","right","RIGHT public column: right or linear");flag.StringVar(&job.marker_column,"marker-column","left","LEFT marker column: left or linear");flag.StringVar(&job.marker,"marker-csv","","separate LEFT trace, required for physical CSV");flag.StringVar(&job.timing_path,"timing","","strict timing/evidence binding JSON");flag.StringVar(&job.method_path,"method","","frozen method-before-models.json");flag.StringVar(&job.profile,"profile","","exact frozen profile name");flag.StringVar(&job.out,"out","","fresh report JSON");flag.StringVar(&job.curve,"csv","","optional fresh unaligned curve CSV");flag.StringVar(&job.noop,"noop-report","","optional same-source matched no-op report");flag.StringVar(&job.calibration,"calibration","","optional same-source matched N1 report");flag.Parse();if flag.NArg()!=1{fmt.Fprintln(os.Stderr,"usage: adapter [flags] RIGHT.csv");os.Exit(2)};job.input=flag.Arg(0);if err:=job.run();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)}}
func(job *history_job)run()error{if job.out==""{return fmt.Errorf("-out required")};if err:=job.load();err!=nil{return err};report,err:=job.analyze();if err!=nil{return err};if err=job.add_references(report);err!=nil{return err};paths:=[]string{job.out};if job.curve!=""{paths=append(paths,job.curve)};if err=history_fresh_paths(paths);err!=nil{return err};if job.curve!=""{if err=job.write_curve(report);err!=nil{return err};report["curve"]=map[string]interface{}{"path":job.curve,"sha256":history_hash_file_must(job.curve)}};data,err:=json.MarshalIndent(report,"","  ");if err!=nil{return err};return history_write_exclusive(job.out,append(data,'\n'))}
func(job *history_job)write_curve(report map[string]interface{})error{file,err:=os.OpenFile(job.curve,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0644);if err!=nil{return err};defer file.Close();writer:=csv.NewWriter(file);if err=writer.Write([]string{"sample","right_pcm","initial_low_prediction_pcm","residual_pcm","n1_scaled_low_ac_coordinate_pcm"});err!=nil{return err};low,_:=report["initial_low_fit"].(*history_fit);var gain *float64;if refs,ok:=report["references"].(map[string]interface{});ok{if cal,ok:=refs["n1_calibration"].(map[string]interface{});ok{gain,_=cal["amplitude_gain"].(*float64)}};for n,v:=range job.right{row:=[]string{strconv.Itoa(n),strconv.FormatFloat(v,'g',17,64),"","",""};if low!=nil{pred:=history_predict(*low,n);row[2]=strconv.FormatFloat(pred,'g',17,64);row[3]=strconv.FormatFloat(v-pred,'g',17,64);if gain!=nil{row[4]=strconv.FormatFloat(*gain*(pred-low.Beta[2]),'g',17,64)}};if err=writer.Write(row);err!=nil{return err}};writer.Flush();return writer.Error()}
